      'larger". Drift alone had printed Pluto to ten figures. The section\'s\n'
      "second half is the case the source's accuracy forced: an ACCURACY\n"
      'STATED ONLY IN WORDS is stored as the place those words report to --\n'
      'the place the Report test gives for every value the words can mean,\n'
      'the coarser where they could mean two -- and never as a number the\n'
      "source does not print. JPL's 2014 report gives three groups, so 1 km,\n"
      '100 km and 10,000 km. The last is one place coarser than the session\n'
      'plan of 2026-10-01 said; Tony confirmed it as recommended the same day.\n'
      'v2.22 settles L-345: A VALUE IN ANOTHER UNIT IS COMPUTED, NEVER STORED,\n'
      'AND ITS COUNT COMES FROM ITS SOURCE ROW ALONE. Each quantity is one row,\n'
      'in the unit its best source gives it, with that source. Its value in\n'
