      "source neither can open fails The Access Standard. A model's read\n"
      'counts and the line says so; a read reconstructed from training is\n'
      'worse than no read, because it stops the next reader from looking. The\n'
      'Unit Field now points at constants_tokens.py, which owns the token\n'
      'table, the RETIRED_TOKENS list and the "named number" marker, and names\n'
      '"# Read:" among the fields a row\'s single slice visit writes. Rule 8\'s\n'
      'enumeration names BOTH routes to a derived row -- its arithmetic and\n'
      'its "# Derived:" line -- because a typed number carrying a\n'
      '"# Derived:" note is a literal whose arithmetic lives in prose, and the\n'
      'checker must still name it. The worksheet schema gains the "Read by"\n'
      'column promised on 2026-09-11 and missed by 2.13. Handle L-322.\n'
      "v2.13 settles L-322 (d), significant figures, on Tony's rulings of\n"
      '2026-09-16. The Figure Count Is a Declared Field [QUALITY] joins\n'
      'Report to the Figures You Have: a "# Figures:" line beside every\n'
      'value, counted by the standard rules (fewest figures for products\n'
      'and quotients, coarsest decimal place for sums and differences,\n'
      'exact and declared numbers never limit a result), computed from the\n'
      'primary inputs at full precision and rounded ONCE at the reporting\n'
      'step, half to even. A Derived Row Stores the Figure Its Sources\n'
      "Support [CRITICAL] is WITHDRAWN on Tony's word of the same day: a\n"
      'rounded literal at rest is a rounded intermediate for every row that\n'
      'chains from it, which is the error the procedure exists to prevent.\n'
      'The store holds the derivation; the export rounds. The Status Line\n'
      'gains The Unit Field, carrying L-322 ruling 1 into the skill, where\n'
      'it had not travelled. Handles L-322, L-325, L-335.\n'
      'v2.12 adds five rules from the L-321 cross-check round and one\n'
      "carried from L-325's Gap. Worksheet Types gains the row-job\n"
      'vocabulary the round actually ran -- [CITATION] and [DISCOVERY] --\n'
      'with the schema that carries it, and two rules that depend on it: A\n'
      'Negative Verdict Shows Its Search [CRITICAL], because UNSOURCED is\n'
      'the one token pointing at no document anybody can open, and Route\n'
      "the Effort Tier by Job Type [QUALITY], Tony's ruling of 2026-09-13.\n"
      'The Access Standard gains a source names what was OPENED, after a\n'
      'checker returned the right URLs under the wrong author names. Step 1\n'
      'of the Review-Repair Protocol gains A Link Is an Object, Not Text\n'
      '[QUALITY] and the three things the prompt must require. The roster\n'
      "records that Gemini's fetching is tier-dependent, so L-276's\n"
      'constraint is about the interface and the tier rather than the\n'
      'vendor, and that a checker inside the Project is not independent for\n'
      'a rerun. A Derived Row Stores the Figure Its Sources Support\n'
      '[CRITICAL] joins The Store Carries the Verified Figure, closing the\n'
      'Gap L-325 parked for this bump. Handles L-321, L-325, L-314.\n'
      'v2.11 adds A Drawing Approximation Does Not Promote [CRITICAL],\n'
      'directly after Measured Is the Goal, Declared Is the Fallback,\n'
      'whose direction of travel it bounds. That section says a declared\n'
      'value is promoted to a measured one as soon as it can be; this one\n'
      'says a number that was never a value -- a shape typed into a\n'
      'renderer because the render looked right -- has nothing to promote\n'
      "and must not be moved into the store. Founding case: Earth's\n"
      'magnetosphere, where a half ellipsoid with typed axes, a conic\n'
      'eccentricity typed at the call site and a sweep cap the code itself\n'
      'labels a MODE-5 KNOB were all candidates for promotion into\n'
      'constants_new.py, and Tony refused it -- "we are not promoting\n'
      'Mode 5 approximations." Handle L-306.\n'
      'v2.10 adds The Store Carries the Verified Figure [CRITICAL] under\n'
      'Report to the Figures You Have, which governed REPORTING and left\n'
      'the stored value uncovered. Founding case: RADIATIVE_ZONE_AU held\n'
      '0.7 beside its own comment saying it rounded 0.713 -- the store\n'
      'recording that it was rounding, and rounding anyway, in a value\n'
      'drawn on a public page. The rule is narrowed in the same breath\n'
      'against the two cases it would damage: a pick from a range stays\n'
      'a declared choice, and a visibility stylization promotes when the\n'
      'physical value becomes drawable rather than for want of digits.\n'
      "Tony's ruling, 2026-08-29, and the reason it is a SKILL rule and\n"
      'not a decision: it resolves the same way next month, for a\n'
      'different constant, in a different file. Handle L-258.\n'
      "v2.9 moves the gate UPSTREAM, from serving to export, on Tony's\n"
      'ruling of 2026-08-28. 2.8 put it where the harm lands; 2.9 puts it\n'
      'where a check can still run. `provenance_scanner.py` exists only in\n'
      'the orrery repo, and `gallery_cache_builder.py` lives in the gallery\n'
      'repo and scores nothing, so a gate at serving sits downstream of the\n'
      'last checker in existence and across a repository boundary. The WHY\n'
      'is unchanged and the WHERE is separated from it explicitly, so the\n'
      'gate cannot drift back on the reasoning that publication is where a\n'
      'visitor is harmed. One section rewritten, nothing else touched.\n'
      "v2.8 adds nine sections and revises four passages, from Tony's\n"
      'rulings of 2026-08-27 and the two independent Mode 7 reviews of the\n'
      'same date. The Gate Binds at SERVING [CRITICAL] moves the binding\n'
      'point from drawing to publication. The Access Standard [CRITICAL]\n'
      'makes reachability a precondition of a citation -- no paywalls.\n'
      'The Status Line [CRITICAL] has each value declare its own provenance\n'
      'state so the scanner reads instead of inferring. Measured Is the\n'
      'Goal, Declared Is the Fallback [CRITICAL] carries the range rule.\n'
      'The Exhibit Requirement [CRITICAL] makes a verdict without a\n'
      'quotation UNVERIFIED. A Cross-Check Retires With Its Value or Its\n'
      'Citation [CRITICAL], Observations Are Sourced Facts [CRITICAL],\n'
      'Uncited Goes to the Ledger [QUALITY], and Examples Go Stale Like\n'
      "Values [QUALITY] complete the set. Revised: the exhibit's reader,\n"
      "Gemini's book access (demoted to lead generation), the\n"
      'two-annotation criterion for V_CROSS_CHECKED (retired -- it measures\n'
      'concurrence), and one stale worked example. Handle L-256.\n'
      "v2.7 adds three sections from Tony's rulings of 2026-08-26, each of\n"
      'them a gap this skill had rather than a refinement of something it\n'
      'said. One Value, One Home [CRITICAL] states positively what No Shadow\n'
      'Constants only prohibited, and extends it to prose and to dead code.\n'
      'Report to the Figures You Have [QUALITY] had no home in any skill.\n'
      'A Breadcrumb Must Not Cite [CRITICAL] records why an honest\n'
      '"pending sourcing" note cannot carry its own references (L-253).\n'
      "Founding case for the first two: Earth's four interior hover strings\n"
      'typed their boundary figures for months beside a radius_fraction that\n'
      'disagreed with them by up to 297 km, and nothing here covered it.\n'
      'v2.6 adds The Two-Dispatch Rule [CRITICAL] under Model Roles in the\n'
      'Competitive Pattern -- L-217, after a Mode 7 review prompt asked two\n'
      'model legs to answer Part A before reading Part B, which neither could\n'
      'do and neither answer could be distinguished on.\n'
      'Source: project_instructions_v3_29.md Part 3 (Provenance Audit, Fetched vs\n'
      'Recalled) + food insecurity build handoff + scanner source at HEAD. v1.1\n'
      'adds the report domain-classification mechanics, the Review-Repair\n'
      'Protocol (promoted from documentation/provenance_audit_handoff_v4.md),\n'
      'and field notes from the F1 provenance-cleanup groundwork session (July\n'
      '2026): the by-file/by-file-type report breakdown, a self-referential\n'
      'scanning quirk, and a stale-audit-doc near-miss. v1.2 updates the\n'
      'role-driven-inclusion bullet for L-163 Phase 3: a coverage gap is\n'
      "resolved by tagging the module's own docstring, since ROLE_MAP is now a\n"
      'regenerated mirror rather than a hand-maintained dict. MODULE_DOMAIN_MAP\n'
      'and classify_domain() are unaffected and remain hand-maintained. v1.3\n'
      'adds No Shadow Constants [CRITICAL]: local copies of constants_new.py\n'
      'values must be deleted and replaced with proper imports -- a frozen copy\n'
      'bypasses the citation chain and drifts silently, same failure class as\n'
      'citing over recalled data. v1.4 rewrites Review-Repair Protocol step 2:\n'
      'cross-checking is the competitive pattern (same worksheet, independent\n'
      "models, Tony compares), not one model reviewing another's output.\n"
      'v1.5 adds Model Roles (tested roles for Claude, GPT, Gemini, Fable in\n'
      'the competitive pattern -- emerged from the Mars and constants_new.py\n'
      'cross-check sessions, August 2026), two worksheet types (value\n'
      'verification vs citation verification), the Cross-checked annotation\n'
      'format, and the Batch Worksheet Workflow. v1.6 adds two rounds to that\n'
      'workflow (blind source lookup and the Fable consistency audit), the\n'
      'model-credit convention, the retirement of the `# Verified:` stamp\n'
      'format, Geometry Constants as First-Class Claims, and three field notes\n'
      '-- all earned in the L-156 Phase 2 Batch 1 cross-check and the Fable\n'
      'shell-consistency audit, August 3-4, 2026. v1.8 adds Worksheet First,\n'
      'Annotation Second (an annotation naming a worksheet that does not exist\n'
      "is cite-to-clear in the annotation's own format) and the field note that\n"
      'an evidence artifact is filed as received -- both earned August 10, 2026,\n'
      'when a recovered worksheet proved an annotation true that the session had\n'
      'already talked itself into calling fabricated.\n'
      'v1.9 narrows The Goal State to the ACTIVE BUILD PATH gate Tony\n'
      'ratified 2026-08-05 (L-184), keeping global Tier-1 = 0 as the\n'
      'stated destination rather than the firing rule. The skill had\n'
      "carried the retired global gate for a week; caught by Fable's\n"
      'document-layer claim audit, finding F1, August 11, 2026.\n'
      '\n'
      'v2.0 (August 12, 2026) replaced the annotation grammar: checker first,\n'
      'optional ` -- <source>` clause, and the retired source-first order now\n'
      'REFUSED as `legacy_source_first` rather than reconstructed. The old\n'
      'order was ambiguous by construction -- a source carrying its own\n'
      'publication year ate the check date, so the model name landed outside\n'
      'the checker identity and two annotations by two DIFFERENT models read\n'
      'as one checker written twice. All 134 lines were migrated. The\n'
      'store-binding check lives in skills_index.py, which asserts that every\n'
      'annotation example in every SKILL.md parses as the scanner reads it --\n'
      'placed there because it runs at the moment a skill changes, which is\n'
      'the moment the drift is introduced.\n'
      '\n'
      'v2.1 (August 13, 2026) extends Worksheet First, Annotation Second with\n'
      'two clauses about what the worksheet has to CONTAIN, and specifies the\n'
      'worksheet table schema and verdict vocabulary at the prompt so the\n'
      'evidence arrives usable. Earned August 12-13: two annotations in\n'
      'constants_new.py credited a worksheet for checks it explicitly did not\n'
      "perform, and one cited worksheet was prose a tool cannot read. Tony's\n"
      'ruling -- we do not have to accept and interpret incomplete or\n'
      'malformed answers -- is the second clause, and the session that\n'
      'produced the evidence can be reopened to finish the job.\n'
      '\n'
      'v2.2 (August 13, 2026) defines DERIVED, which v2.1 listed in the\n'
      'verdict vocabulary without ever saying what it meant, and separates\n'
      'two things the send-back rule had run together. A row that is\n'
      'INCOMPLETE goes back to its originator. A row that is COMPLETE and\n'
      'disagrees with the code is a FINDING and comes to conversation,\n'
      'because the disagreement may be a convention mismatch rather than an\n'
      'error in either place. Earned August 13 on the Eris and Pluto Hill\n'
      'sphere rows, where checkers computing at semimajor axis disagreed\n'
      'with code computing at perihelion and nobody had done bad\n'
      "arithmetic. Tony's rulings: PARTIAL and APPROX return\n"
      'unconditionally, and an adjudication is recorded with its reason so\n'
      'the next run does not re-raise it.\n'
      '\n'
      'The resident protocol carries the two governing principles as CRITICAL\n'
      'gates: Fetched-vs-Recalled (a citation is a provenance claim that must be\n'
      'TRUE; source-then-cite, never cite-to-clear) and Show the Envelope of the\n'
      "Unknowable. This skill carries the working procedures and the scanner's\n"
      'mechanics. If this skill and the resident gates ever seem to disagree, the\n'
      'gates win -- flag it.\n'
      '\n'
      '\n'
      'v2.4 (August 17, 2026) carries three changes, all earned the same day.\n'
      'The annotation grammar now accepts a `.jsonl` or `.json` worksheet\n'
      'reference as well as `.md` (L-204). The `.md` condition did two jobs:\n'
      'it required the parenthetical to name a FILE rather than free prose,\n'
      'which is the anti-gaming half of L-186 and does not move, and it\n'
      'pinned the only worksheet format that existed in August 2026. The JSON\n'
      'return format (L-202) landed 2026-08-17, and a returned verdict could\n'
      'then be built, carried, filled, checked and routed -- and refused by\n'
      'that one condition when somebody wrote it back into the code. Found by\n'
      'an integration test, not by a reading. The Resolved Leg section is new\n'
      '(L-200): a record-only leg saying which returned verdict caused an\n'
      'edit. And The Visibility Convention is new (L-203), promoting a\n'
      'one-off ruling about the request builder into the general rule it was\n'
      'always an instance of.\n'
      '\n'
      'v2.5 (August 18, 2026) adds Extend a Boundary Before Adding a Path,\n'
      'the rule an external review proposed on 2026-08-18 and Tony adopted\n'
      'the same day. It lives here rather than in the resident protocol\n'
      'because it fires while a provenance feature is being designed, which\n'
      'is when this skill loads. L-207, the citation prompt, was the first\n'
      'item checked against it rather than assumed to pass.\n'
      '\n'
