      '## safe-file-editing\n'
      '\n'
      'Source: project_instructions_v3_29.md Part 3 + Part 5 technical lessons;\n'
      'v1.1 adds the delivery-format convention from a same-day incident (a\n'
      'transactional patch silently never run; see Field Notes). v1.3 adds\n'
      'Line Endings Are Not Content, earned when a patch aborted twice on a\n'
      "CRLF working copy whose bytes were identical to the repo's. v1.4 adds\n"
      'Fix In Passing, Report It, after a patch blocked itself on two Unicode\n'
      'arrows that predated it by months, and Naming and Archiving a Patch\n'
      'Script, an unstated convention 96 scripts deep that Tony had been\n'
      'following alone. v1.5 adds Stamp What You Change (L-220), after Tony\n'
      'observed that this project updates bodies more reliably than it updates\n'
      'anchors, dates and module descriptions. v1.6 generalises that section to\n'
      "every file type, because 1.5's only concrete example was a Python module\n"
      "docstring and the rule's founding case was stale Markdown headers -- it\n"
      'would not have fired on the files it was written for. v1.7 adds A Paste\n'
      'Is An Unverified Transfer (L-223), which extends the delivery rule to\n'
      'prose, markdown and ledger files -- every example in 1.6 was code, and\n'
      'this project had been hand-editing a 579 KB ledger on that silence.\n'
      "v1.8 (L-226) does two things, both from Tony's rulings of 2026-08-23.\n"
      'It rescopes the Encoding Gate to say PROSE explicitly, because a\n'
      'session read "delivered code" as excluding markdown and left 23\n'
      'non-ASCII characters in a file it was already patching. And it adds\n'
      'The Correction Does Not Travel, one scope out from Stamp What You\n'
      'Change: that section governs the file the patch is editing, this one\n'
      'governs the other files quoting the value it just changed.\n'
      '\n'
      '## orrery-coding-conventions\n'
      '\n'
      'v1.6 (L-249) makes the angular step in Marker Separation for\n'
      'Near-Equal Radii an OUTCOME rather than a fixed 20 degrees, with 20 and\n'
      "10 recorded as the two worked cases. Earned when Earth's upper mantle\n"
      "moved to its sourced radius and its cross vanished under the crust's.\n"
      'Source: project_instructions_v3_29.md Part 3 + Part 5 technical lessons.\n'
      'v1.4 adds Marker Separation for Near-Equal Radii to the Single Info\n'
      'Marker Pattern, earned when the chromosphere moved to true scale and its\n'
      "marker landed one pixel from the photosphere's; and Harvest the\n"
      'Conventions You Find, which is how this skill grows.\n'
      'v1.5 (L-227) adds Hover Line Width Is a Convention, Not an Accident,\n'
      'found by Mode 5 when a tooltip ran off the viewport: a hover string had\n'
      'been wrapped at 72 characters in the SOURCE with no `<br>` on the\n'
      'lines, and rendered as one 378-character run. Canonical Text Format\n'
      'already governed `\\n` versus `<br>` and said nothing about width.\n'
      '\n'
      'v1.2 adds the conventions earned in the L-156 Phase 2 Batch 1 cross-check\n'
      'and the Fable shell-consistency audit (August 3-4, 2026): the\n'
      'visualization-constant-vs-range convention, the Hill sphere documentation\n'
      'standard (including the measured per-body state, which does NOT yet match\n'
      'the intended convention), the canonical `\\n` direction for module _info\n'
      'strings, dual-pipeline detail added to the shell dispatch section, and\n'
      'layer-chain gap handling. Two field notes added.\n'
      '\n'
