      'module is classified by tagging its own docstring, not by hand-adding a\n'
      'ROLE_MAP entry, because ROLE_MAP became a regenerated mirror that the\n'
      'next module_atlas.py run overwrites. v1.7 adds Cluster the Tail by\n'
